/**
 * Priorities for a piece of advice (or a bundle) can be any value.
 * The higher priority values tend to be evaluated first.
 * These enums are provided as a handy standard set to use.
 */
export enum AdvicePriority {
	Low = 50,
	Default = 100,
	High = 200,
	Utmost = 300,
}

/**
 * Choose to perform selection every X turns.
 * @param turns how many turns to wait for a selet to occur.
 * @param offset offset from 0
 * @returns true if the current turn alignes with turns and the offset
 */
export function selectAfterTurns(turns: number, offset = 0): boolean {
	const turn = Game.turn;
	return (turn - 1 + offset) % turns == 0;
}

// Set the turns to wait before delivering certain advice, based on game speed.
// Save these as consts on the module level as they are commonly used and this
// will prevent having to recalculate them multiple times in the same session.
const { gameSpeedType } = Configuration.getGame();
const gameSpeedObj = GameInfo.GameSpeeds.lookup(gameSpeedType);
const gameSpeed = gameSpeedObj!.CostMultiplier;
const gameSpeedMultiplier = gameSpeed ? gameSpeed / 100 : 1;

/**
 * Determine if a piece of advice should be selected based on the current turn and game speed
 * @param start The turn number to start selecting advice.
 * @param duration The duration in turns for which the advice should be selected.
 * @param offset An optional offset to stagger advice selection.
 * @return true if the advice should be selected on the current turn, false otherwise.
 */
export function shouldSelect(start: number, durration: number, offset = 0): boolean {
	const turn = Game.turn;
	if (turn < start) {
		return false;
	}
	const durrationAdjusted = Math.floor(durration * gameSpeedMultiplier);
	const offsetAdjusted = Math.floor(offset * gameSpeedMultiplier);
	if (turn + offsetAdjusted == start) {
		return true;
	}
	return (turn - 1 + offsetAdjusted) % durrationAdjusted == 0;
}

/**
 * Does local player have at least X wonders?
 * @param amount Number of wonders to have.
 * @return true if player has at least the amount of wonders
 */
export function hasWonders(amount: number): boolean {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (player && player.Stats) {
		const originalConstructor = false; // Ignore if player was original constructor
		const currentAgeOnly = false;
		return player.Stats.getNumWonders(originalConstructor, currentAgeOnly) >= amount;
	}
	return false;
}

/**
 * Does local player have a specific civic?
 * @param name The identifier of a civic node (e.g., "NODE_CIVIC_AQ_MAIN_CODE_OF_LAWS")
 * @returns true if player has the civic, false otherwise.
 */
export function hasCivic(name: string): boolean {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (player && player.Culture) {
		return player.Culture?.isNodeUnlocked(name);
	}
	return false;
}

/**
 * Does local player have gold in a specific range?
 * @param min Minimum amount (inclusive) or -1 for no minimum.
 * @param max Maximum amount (inclusive) or -1 for unbounded (no maximum).
 * @returns true if player has gold in that range.
 */
export function goldInRange(min: number, max: number): boolean {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (!player) {
		return false;
	}
	const treasury = player.Treasury;
	if (!treasury) {
		return false;
	}
	return (treasury.goldBalance >= min || min == -1) && (treasury.goldBalance <= max || max == -1);
}

/**
 * If any of the supplied names of tech nodes are unlocked.
 * @param names An array of tech node names.
 * @returns true if any one of them has been unlocked.
 */
export function anyTechUnlocked(names: string[]): boolean {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (player) {
		const playerTechs: PlayerTechs | undefined = player.Techs;
		if (playerTechs) {
			for (const techName of names) {
				if (playerTechs.isNodeUnlocked(techName)) {
					return true;
				}
			}
		}
	}
	return false;
}

/**
 * Is the local player at war with any other major civilizations?
 * @returns true if at war.
 */
export function isAtWar(): boolean {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (player) {
		const playerDiplomacy: PlayerDiplomacy | undefined = player.Diplomacy;
		if (playerDiplomacy) {
			if (playerDiplomacy.isAtWarWithAnyMajorCiv() == true) {
				return true;
			}
		}
	}
	return false;
}

/**
 * @returns The number of conquered settlements.
 */
export function amountConqueredSettlements(): number {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (!player || !player.Stats) {
		return 0;
	}
	const countMinorPlayers = true;
	const countHomelands = true;
	const countDistantLands = true;
	const bCoastalOnly = false;
	return player.Stats.getNumConqueredSettlements(countMinorPlayers, countHomelands, countDistantLands, bCoastalOnly);
}

/**
 * @returns The true if player has created a religion.
 */
export function playerHasReligion(): boolean {
	const player: PlayerLibrary | null = Players.get(GameContext.localPlayerID);
	if (!player || !player.Religion) {
		return false;
	}
	return player.Religion.hasCreatedReligion();
}
